{"path": "src/riskscore/recency.py", "content": """"How long before the end of the fit window the product last traded and the
account last ordered."""
import numpy as np
import pandas as pd


def sku_last_trade(fit_df):
    return fit_df.groupby("sku")["placed_at"].max()


def account_last_order(fit_df):
    return fit_df.groupby("account_id")["placed_at"].max()


def staleness(last_seen, fit_end):
    return (fit_end - last_seen).dt.days.astype("float64")


def add(df, sku_stale, account_stale, stale_prior):
    out = df.copy()
    out["f_sku_days_since_trade"] = out["sku"].map(sku_stale).fillna(stale_prior)
    out["f_account_days_since_order"] = out["account_id"].map(account_stale).fillna(-1.0)
    return out
"}

{"path": "src/riskscore/cadence.py", "content": """"How regularly the product trades and the account orders."""
import numpy as np
import pandas as pd


def sku_trade_days(fit_df):
    days = fit_df["placed_at"].dt.normalize()
    return fit_df.assign(_day=days).groupby("sku")["_day"].nunique().astype("float64")


def account_gap(fit_df):
    days = fit_df["placed_at"].dt.normalize()

    def mean_gap(s):
        s = s.drop_duplicates().sort_values()
        if len(s) < 2:
            return np.nan
        return s.diff().dropna().dt.total_seconds().mean() / 86400.0

    gaps = fit_df.assign(_day=days).groupby("account_id")["_day"].apply(mean_gap)
    portfolio = float(gaps.mean())
    return gaps.astype("float64"), portfolio


def add(df, trade_days, gaps, portfolio_gap):
    out = df.copy()
    out["f_sku_trade_days"] = out["sku"].map(trade_days).fillna(0.0)
    out["f_account_order_gap"] = out["account_id"].map(gaps).fillna(portfolio_gap)
    return out
"}

{"path": "src/riskscore/dispersion.py", "content": """"How much a sku's price has moved around its own usual level.

Lines priced unusually for their own sku are the ones that get sent back.
"""
import numpy as np
import pandas as pd


def price_dispersion(fit_df):
    def mad(s):
        return (s - s.mean()).abs().mean()

    return fit_df.groupby("sku")["unit_price"].apply(mad).astype("float64")


def add(df, dispersion):
    out = df.copy()
    prior = float(dispersion.mean())
    out["f_sku_price_dispersion"] = out["sku"].map(dispersion).fillna(prior)
    return out
"}

{"path": "src/riskscore/concentration.py", "content": """"How wide a price band a sku has traded in over the fit window."""
import numpy as np
import pandas as pd


def price_range(fit_df):
    grp = fit_df.groupby("sku")["unit_price"]
    return (grp.max() - grp.min()).astype("float64")


def add(df, spread):
    out = df.copy()
    prior = float(spread.mean())
    out["f_sku_price_range"] = out["sku"].map(spread).fillna(prior)
    return out
"}

