import numpy as np
import pandas as pd


def factor_table(fit_df, label):
    return fit_df.groupby("f_month")[label].mean().astype("float64")


def add(df, factors):
    out = df.copy()
    fallback = float(factors.mean())
    out["f_seasonal"] = out["f_month"].map(factors).fillna(fallback)
    return out
